import { useMemo } from 'react';
import { Link, useSearchParams } from 'react-router-dom';

import productData from '../data/fireworks/productData.js';
import onlyUnique from '../functions/onlyUnique.js';
import usePageMeta from '../functions/usePageMeta.js';
import VideoSection from '../components/VideoSection.js';

const ALL_CATEGORY = 'visi';

const categoryLabel = (category) => {
  if (category === ALL_CATEGORY) return 'Visi';
  return category.charAt(0).toUpperCase() + category.slice(1);
};

const getCategory = (product) =>
  product.info.find((el) => el.name === 'Kategorija')?.value || '';

const getPrice = (product) => Number(product.price[0].value);

const LandingPage = () => {
  usePageMeta({
    title: 'Mūsu pirotehnika',
    description:
      'Tropiks AZ pirotehnikas katalogs — baterijas, raķetes, romiešu sveces un citi izstrādājumi Rīgā.',
    path: '/',
  });

  const [searchParams, setSearchParams] = useSearchParams();

  const selectedCategory = searchParams.get('kategorija') || ALL_CATEGORY;
  const selectedPrice = searchParams.get('cena') === 'ascending' ? 'ascending' : 'descending';
  const searchQuery = searchParams.get('q') || '';

  const categoryList = useMemo(() => {
    const categories = productData.map(getCategory).filter(Boolean).filter(onlyUnique);
    return [ALL_CATEGORY, ...categories];
  }, []);

  const productList = useMemo(() => {
    let products = productData.filter(
      (product) => product.meta[0].display === 'yes' && product.meta[0].sold !== 'yes'
    );

    if (selectedCategory !== ALL_CATEGORY) {
      products = products.filter((product) => getCategory(product) === selectedCategory);
    }

    const query = searchQuery.trim().toLowerCase();
    if (query) {
      products = products.filter((product) => {
        const haystack = `${product.id} ${product.name} ${getCategory(product)}`.toLowerCase();
        return haystack.includes(query);
      });
    }

    products = [...products].sort((a, b) =>
      selectedPrice === 'ascending' ? getPrice(a) - getPrice(b) : getPrice(b) - getPrice(a)
    );

    return products;
  }, [selectedCategory, selectedPrice, searchQuery]);

  const updateParam = (key, value, clearWhenEmpty = false) => {
    const next = new URLSearchParams(searchParams);
    if (clearWhenEmpty && (!value || value === ALL_CATEGORY || value === 'descending')) {
      if (key === 'kategorija' && value === ALL_CATEGORY) next.delete(key);
      else if (key === 'cena' && value === 'descending') next.delete(key);
      else if (!value) next.delete(key);
      else next.set(key, value);
    } else if (!value) {
      next.delete(key);
    } else {
      next.set(key, value);
    }
    setSearchParams(next, { replace: true });
  };

  return (
    <section>
      <VideoSection />

      <main className="landing-page" id="katalogs">
        <section className="main-landing-page-title">
          <h2>
            MŪSU <span>PIROTEHNIKA</span>
          </h2>
          <p className="landing-subtitle">
            Filtrējiet pēc kategorijas, meklējiet pēc nosaukuma vai koda un salīdziniet cenas.
          </p>
        </section>

        <section id="filtri" className="catalog-filters" aria-label="Produktu filtri">
          <section className="product-filters">
            <section className="product-filter product-filter-search">
              <label htmlFor="productSearch">MEKLĒT</label>
              <input
                id="productSearch"
                type="search"
                name="q"
                placeholder="Nosaukums vai kods"
                value={searchQuery}
                onChange={(event) => updateParam('q', event.target.value)}
              />
            </section>

            <section className="product-filter">
              <label htmlFor="priceSelect">CENA</label>
              <select
                id="priceSelect"
                name="priceSelector"
                value={selectedPrice}
                onChange={(event) => updateParam('cena', event.target.value, true)}
              >
                <option value="descending">Sākot ar augstāko</option>
                <option value="ascending">Sākot ar zemāko</option>
              </select>
            </section>
          </section>

          <section className="category-chips" aria-label="Kategorijas">
            {categoryList.map((category) => (
              <button
                key={category}
                type="button"
                className={`category-chip${selectedCategory === category ? ' active' : ''}`}
                onClick={() => updateParam('kategorija', category, true)}
              >
                {categoryLabel(category)}
              </button>
            ))}
          </section>
        </section>

        <p className="product-count" aria-live="polite">
          Atrasti {productList.length} produkti
        </p>

        <section className="product-display">
          {productList.length <= 0 ? (
            <section className="product-display-empty animate pop">
              <p>
                Pašlaik mūsu noliktavā nav pieejami pirotehniskie izstrādājumi, kas atbilstu Jūsu
                meklētajiem kritērijiem.
              </p>
            </section>
          ) : (
            productList.map((product) => {
              const isNew = product.meta[0].new === 'yes';

              return (
                <article key={product.id} className="product-card animate pop">
                  <Link to={`/produkti/${product.id}`} className="product-link">
                    <section className="product-card-img">
                      {isNew && (
                        <div className="product-badges">
                          <span className="product-badge product-badge-new">Jaunums</span>
                        </div>
                      )}
                      <picture>
                        <source type="image/webp" srcSet={product.media[0].webp} />
                        <img
                          alt={`Foto ar pirotehnisko izstrādājumu ${product.name} - ${product.id}`}
                          src={product.media[0].img}
                          width="280"
                          height="280"
                          loading="lazy"
                          decoding="async"
                        />
                      </picture>
                    </section>

                    <section className="product-card-info">
                      <h3>
                        {product.id}
                        <br />
                        {product.name}
                      </h3>
                      <p className="product-card-category">{categoryLabel(getCategory(product))}</p>
                      <p className="product-card-info-price">
                        {product.price[0].value} {product.price[0].symbol}
                      </p>
                    </section>
                  </Link>
                </article>
              );
            })
          )}
        </section>
      </main>
    </section>
  );
};

export default LandingPage;
